import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import NewsItem from './NewsItem';
import { Form } from 'react-bootstrap';

const NewsList: React.FC = () => {
  const { articles, status } = useSelector((state: RootState) => state);
  const [authorFilter, setAuthorFilter] = useState('');
  const [filteredArticles, setFilteredArticles] = useState(articles);

  useEffect(() => {
    // ✅ Apply frontend filtering
    const filtered = articles.filter(article => {
      const articleAuthor = article.author ? article.author.toString().trim().toLowerCase() : '';
      return authorFilter === '' || articleAuthor.includes(authorFilter.trim().toLowerCase());
    });

    setFilteredArticles(filtered);
  }, [authorFilter, articles]);

  if (status === 'loading') return <p>Loading...</p>;
  if (status === 'failed') return <p>Failed to load news.</p>;

  return (
    <div>
      {filteredArticles.length > 0 ? (
        filteredArticles.map((article, index) => <NewsItem key={index} article={article} />)
      ) : (
        <p>No articles found for the selected author.</p>
      )}
    </div>
  );
};

export default NewsList;
